referenceSolutions.javascript:
function recursiveShelvesFirstQualifyingSlip(readings, k) {
  const a=readings; let out=[];
  function visit(l,r){if(l>=r)return;let s=0;for(let i=l;i<r;i++)s+=a[i];out.push(s);if(r-l>1){const m=Math.floor((l+r)/2);visit(l,m);visit(m,r);}}visit(0,a.length);
  return out.find(x=>x>=k)??-1;
}

